def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def remove_duplicates(numbers: List[int]) -> List[int]:
    """ From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.
    >>> remove_duplicates([1, 2, 3, 2, 4])
    [1, 3, 4]
    """
    count = {}
    for num in numbers:
        count[num] = count.get(num, 0) + 1

    return [num for num in numbers if count[num] == 1]

def minPath(grid, k):
    n = len(grid)

    # Find the position of value 1 in the grid
    start_pos = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_pos = (i, j)
                break
        if start_pos:
            break

    # DFS with memoization to find the lexicographically smallest path
    memo = {}

    def dfs(i, j, remaining):
        # remaining is the number of cells we still need to visit
        if remaining == 0:
            return []

        if (i, j, remaining) in memo:
            return memo[(i, j, remaining)]

        current_val = grid[i][j]

        # If this is the last cell to visit
        if remaining == 1:
            return [current_val]

        # Try all four directions
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        best_path = None

        for di, dj in directions:
            ni, nj = i + di, j + dj

            # Check bounds
            if 0 <= ni < n and 0 <= nj < n:
                rest_path = dfs(ni, nj, remaining - 1)
                current_path = [current_val] + rest_path

                # Keep the lexicographically smallest path
                if best_path is None or current_path < best_path:
                    best_path = current_path

        memo[(i, j, remaining)] = best_path
        return best_path

    result = dfs(start_pos[0], start_pos[1], k)
    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result = [word for word in words if is_prime(len(word))]
    return " ".join(result)

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even_count = 0
    odd_count = 0

    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)
